// An ES module package whose pieces load through import() with a computed
// specifier: scriptc cannot compile that natively, so it runs in a Node
// island.
let total = 0;
export const label = "tally";
export function bump() {
  total += 1;
  return total;
}
export async function piece(name) {
  const loaded = await import(`./pieces/${name}.js`);
  return loaded.size;
}
